                            "display_name": package_name,
                            "version": parts[1],
                            "manager": "pacman",
                            "licenses": self._get_pacman_license(package_name)
                        }
                        packages.append(package_info)
            return packages
        except (subprocess.CalledProcessError, FileNotFoundError):
            return []

