    def __init__(self):
        super().__init__("Pacman", "pacman")
        self.cache = get_license_cache()

    def get_installed_packages(self) -> List[Dict[str, any]]:
        """Get installed Pacman packages with license information (optimized)."""
        try:
            # Get all packages in one call
            result = subprocess.run(
                ["pacman", "-Q"],
                capture_output=True,
                text=True,
                check=True
            )

            # Parse package list
            package_list = []
            for line in result.stdout.strip().split('\n'):
                if line.strip():
                    parts = line.split()
                    if len(parts) >= 2:
                        package_list.append((parts[0], parts[1]))

            # Get licenses for all packages concurrently
            packages = self._get_packages_with_licenses_concurrent(package_list)
            return packages

        except (subprocess.CalledProcessError, FileNotFoundError):
            return []

    def _get_packages_with_licenses_concurrent(self, package_list: List[Tuple[str, str]]) -> List[Dict[str, any]]:
        """Get package information with licenses using concurrent processing."""
        packages = []

        # Separate cached and uncached packages
        cached_packages = []
        uncached_packages = []

        for package_name, version in package_list:
            cached_licenses = self.cache.get("pacman", package_name, version)
            if cached_licenses is not None:
                cached_packages.append({
                    "name": package_name,
                    "display_name": package_name,
                    "version": version,
                    "manager": "pacman",
                    "licenses": cached_licenses
                })
            else:
                uncached_packages.append((package_name, version))

        packages.extend(cached_packages)

        # Process uncached packages concurrently
        if uncached_packages:
            # Use ThreadPoolExecutor for concurrent license fetching
            max_workers = min(32, len(uncached_packages))  # Limit concurrent processes

            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                # Submit all license fetch tasks
                future_to_package = {
                    executor.submit(self._get_pacman_license_single, pkg_name, version): (pkg_name, version)
                    for pkg_name, version in uncached_packages
                }

                # Collect results as they complete
                for future in as_completed(future_to_package):
                    package_name, version = future_to_package[future]
                    try:
                        licenses = future.result()

                        # Cache the result
                        self.cache.set("pacman", package_name, version, licenses)

                        packages.append({
                            "name": package_name,
                            "display_name": package_name,
                            "version": version,
                            "manager": "pacman",
                            "licenses": licenses
                        })
                    except Exception as e:
                        # If license fetch fails, use unknown
                        packages.append({
                            "name": package_name,
                            "display_name": package_name,
                            "version": version,
                            "manager": "pacman",
                            "licenses": ["unknown"]
                        })

        return packages

    def _get_pacman_license_single(self, package_name: str, version: str) -> List[str]:
